package store

import "strings"

import "testing"

func TestTranslateSchemaPostgres(t *testing.T) {
	in := `CREATE TABLE IF NOT EXISTS runs (
	id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	continue_on_error BOOLEAN NOT NULL DEFAULT 0,
	resume BOOLEAN NOT NULL DEFAULT 1,
	retries INTEGER NOT NULL DEFAULT 0,
	id1 INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT CHECK (id1 = 1)
);`
	out := translateSchema(in)

	cases := map[string]bool{
		"BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY": true, // AUTOINCREMENT -> IDENTITY
		"AUTOINCREMENT":                      false, // none left
		"DATETIME":                           false, // all -> TEXT
		"created_at TEXT":                    true,  // datetime column became text
		"to_char((now() AT TIME ZONE 'utc')": true,  // CURRENT_TIMESTAMP default
		"continue_on_error BOOLEAN NOT NULL DEFAULT FALSE": true, // bool default 0 -> FALSE
		"resume BOOLEAN NOT NULL DEFAULT TRUE":             true, // bool default 1 -> TRUE
		"retries INTEGER NOT NULL DEFAULT 0":               true, // integer default 0 untouched
		"CHECK (id1 = 1)":                                  true, // trailing check preserved
	}
	for sub, want := range cases {
		if got := strings.Contains(out, sub); got != want {
			t.Errorf("translateSchema: contains %q = %v, want %v\n---\n%s", sub, got, want, out)
		}
	}
}

func TestTranslateMigrationAddColumnIfNotExists(t *testing.T) {
	out := translateMigration("ALTER TABLE runs ADD COLUMN paused_at DATETIME")
	if !strings.Contains(out, "ADD COLUMN IF NOT EXISTS paused_at TEXT") {
		t.Errorf("translateMigration = %q", out)
	}
}

func TestRebindPostgres(t *testing.T) {
	d := dialectPostgres
	if got := d.rebind("SELECT * FROM t WHERE a=? AND b=?"); got != "SELECT * FROM t WHERE a=$1 AND b=$2" {
		t.Errorf("rebind = %q", got)
	}
	// a ? inside a string literal must be left alone.
	if got := d.rebind("SELECT '?' , x WHERE y=?"); got != "SELECT '?' , x WHERE y=$1" {
		t.Errorf("rebind literal = %q", got)
	}
	// SQLite is the identity.
	if got := dialectSQLite.rebind("a=? b=?"); got != "a=? b=?" {
		t.Errorf("sqlite rebind changed query: %q", got)
	}
}
